./novamind-operation python-c "
import novamind_api as nm

# Check recent ad channel leads
r = nm.query('SELECT day, channel_id, group_id, leads_generated, spend FROM ad_channel_leads WHERE day >= 21 ORDER BY day DESC LIMIT 80')
print('--- Ad Channel Leads (days 21-28) ---')
days = {}
for row in r['rows']:
    d = row['day']
    if d not in days: days[d] = {}
    g = row['group_id']
    if g not in days[d]: days[d][g] = {'leads': 0, 'spend': 0}
    days[d][g]['leads'] += row['leads_generated']
    days[d][g]['spend'] += row['spend']

for d in sorted(days.keys(), reverse=True):
    print(f'Day {d}:')
    for g in ['S1','S2','S3','E1','E2','E3']:
        if g in days[d]:
            print(f'  {g}: {days[d][g][\"leads\"]} leads, \${days[d][g][\"spend\"]:.0f}')

# Check daily burn - recent 7 days of ledger
r2 = nm.query('SELECT day, SUM(amount) as daily FROM (SELECT CAST((entry_day-1)/7 AS INT)*7+1 as day_bucket, amount FROM ledger WHERE entry_day >= 22 AND entry_day <= 28) GROUP BY day_bucket')
# Hmm let me try differently
r2 = nm.query('SELECT SUM(CASE WHEN type=\"expense\" THEN amount ELSE 0 END) as expenses, SUM(CASE WHEN type=\"revenue\" THEN amount ELSE 0 END) as revenue FROM ledger')
print(f'\nLedger summary: ')
for row in r2['rows']: print(f'  {row}')
"

