./novamind-operation python-c "
import novamind_api as nm

# Get detailed market overview
overview = nm.market.get_market_overview()
print('=== Market Overview ===')
for g in overview.get('known_groups', []):
    print(f'  Group {g[\"group_id\"]}: type={g[\"type\"]}, cap={g[\"market_cap\"]}, current={g[\"current_subscribers\"]}, info_level={g.get(\"info_level\",\"?\")}, q_min={g.get(\"q_min\",\"?\")}, wtp={g.get(\"wtp\",\"?\")}')

print(f'\nMacro: {overview.get(\"macroeconomic\",{})}')

# Get group insights for each known group
for group in ['S1', 'S2', 'S3', 'E1', 'E2', 'E3']:
    try:
        insights = nm.market.get_group_insights(group_id=group)
        print(f'\n=== {group} Insights ===')
        # Print key fields
        for k, v in insights.items():
            if isinstance(v, (int, float, str, bool)):
                print(f'  {k}: {v}')
            elif isinstance(v, list):
                print(f'  {k}: [{len(v)} items]')
            elif isinstance(v, dict):
                print(f'  {k}: {dict(list(v.items())[:5])}')
    except Exception as e:
        print(f'  {group} insights error: {e}')

# Also get cost info
cost_info = nm.infrastructure.get_cost_info()
print(f'\n=== Cost Info ===')
for k, v in cost_info.items():
    print(f'  {k}: {v}')
"

