./novamind-operation python-c "
import novamind_api as nm

# Check R&D projects properly
projects = nm.research.list_research_projects()
print('=== R&D Projects ===')
if isinstance(projects, list):
    for p in projects:
        if isinstance(p, dict):
            print(f'  Tier {p.get(\"tier\")}: status={p.get(\"status\")} | boost={p.get(\"quality_boost\")} | cost={p.get(\"cost\")}')
        else:
            print(f'  {p}')
elif isinstance(projects, dict):
    for k, v in projects.items():
        print(f'  {k}: {v}')
else:
    print(f'  Raw: {projects}')

# Check market overview for groups
overview = nm.market.get_market_overview()
print('\n=== Market Groups ===')
if 'groups' in overview:
    for g in overview['groups']:
        print(f'  {g.get(\"group_id\")}: discovered={g.get(\"discovered\")}, info_level={g.get(\"info_level\")}, cap={g.get(\"market_cap\")}, subs={g.get(\"current_subscribers\")}')

# Check subscription distribution more carefully
print('\n=== S1 effective prices ===')
r = nm.query('SELECT s.plan, AVG(s.effective_price) as avg_eff, MIN(s.effective_price) as min_eff, MAX(s.effective_price) as max_eff, COUNT(*) as n FROM subscriptions s JOIN customers c ON s.customer_id = c.customer_id WHERE s.status=\"subscribed\" AND c.group_id=\"S1\" GROUP BY s.plan')
for row in r['rows']:
    print(f'  Plan {row[\"plan\"]}: avg=\${row[\"avg_eff\"]:.2f}, min=\${row[\"min_eff\"]:.2f}, max=\${row[\"max_eff\"]:.2f}, n={row[\"n\"]}')
"

