import novamind_api as nm

# Check group insights for key groups
for gid in ['S1', 'S2', 'S3', 'E1', 'E2', 'E3']:
    try:
        insights = nm.market.get_group_insights(group_id=gid)
        print(f'=== {gid} Insights ===')
        print(f'  Expected quality: {insights.get(\"expected_quality\", \"N/A\")}')
        print(f'  Info level: {insights.get(\"info_level\", \"N/A\")}')
        # Check referral rates
        ref = insights.get('referral_rates', {})
        if ref:
            print(f'  Referral rates (leads/1000 subs/day):')
            for src, rate in ref.items():
                if rate > 0.01:
                    print(f'    {src} -> {gid}: {rate:.4f}')
    except Exception as e:
        print(f'  {gid}: Error - {e}')

# Check market overview 
overview = nm.market.get_market_overview()
print('\\n=== Market Overview ===')
for key, val in overview.items():
    if key != 'groups':
        print(f'  {key}: {val}')
if 'groups' in overview:
    print(f'  Groups discovered: {len(overview[\"groups\"])}')
    for g in overview['groups'][:10]:
        print(f'    {g}')
"

./novamind-operation python-c "
import novamind_api as nm

# Fix enterprise turns query
print('=== ENTERPRISE TURNS (open) ===')
et = nm.query('SELECT * FROM enterprise_turns WHERE closed=0 LIMIT 20')
rows = et.get('rows', [])
print(f'Count: {len(rows)}')
for row in rows:
    print(f'  msg_id={row[\"message_id\"]} cust={row[\"customer_id\"]} type={row[\"thread_type\"]} turn={row[\"turn_number\"]} day={row[\"day\"]}')

print()
print('=== ENTERPRISE TURNS (recent 14 days, all) ===')
et2 = nm.query('SELECT message_id, customer_id, thread_type, turn_number, closed, day FROM enterprise_turns WHERE day >= 105 ORDER BY day DESC LIMIT 30')
for row in et2.get('rows', []):
    print(f'  msg_id={row[\"message_id\"]} cust={row[\"customer_id\"]} type={row[\"thread_type\"]} turn={row[\"turn_number\"]} closed={row[\"closed\"]} day={row[\"day\"]}')

print()
print('=== MARKET OVERVIEW ===')
ov = nm.market.get_market_overview()
print(f'Keys: {list(ov.keys()) if ov else \"None\"}')
if ov:
    for k, v in ov.items():
        if isinstance(v, dict):
            print(f'{k}:')
            for k2, v2 in v.items():
                print(f'  {k2}: {v2}')
        else:
            print(f'{k}: {v}')

# Try getting group insights with proper handling
print()
for g in ['S1', 'S2', 'S3']:
    print(f'=== GROUP INSIGHTS: {g} ===')
    try:
        ins = nm.market.get_group_insights(group_id=g)
        if ins:
            print(f'Type: {type(ins)}')
            print(f'Keys: {list(ins.keys())}')
            for k, v in ins.items():
                if isinstance(v, (int, float, str, bool, type(None))):
                    print(f'  {k}: {v}')
                elif isinstance(v, dict):
                    print(f'  {k}: (dict with {len(v)} keys)')
                    for k2, v2 in list(v.items())[:5]:
                        print(f'    {k2}: {v2}')
                elif isinstance(v, list):
                    print(f'  {k}: (list with {len(v)} items)')
                else:
                    print(f'  {k}: {type(v)}')
    except Exception as e:
        print(f'  ERROR: {e}')
    print()
"

